// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.reminderimport timber.log.Timberimport android.os.Buildimport android.security.keystore.KeyGenParameterSpecimport android.security.keystore.KeyPropertiesimport android.util.Base64import com.roshan.persona.productivity.alarm.EncryptedDataimport java.security.KeyStoreimport javax.crypto.Cipherimport javax.crypto.KeyGeneratorimport javax.crypto.SecretKeyimport javax.crypto.spec.GCMParameterSpec/** * NOUS — Reminder Encryption Helper (Module 14 v1.2 — Step 14.2, CRITICAL). * * REAL AndroidKeystore-backed AES-256-GCM encryption for reminder bodies. * This is NOT a stub — every method uses REAL Android cryptographic APIs. * * ## Why encrypt reminder bodies? * * Per strategy v1.2 §"Polish 6" + v1.1 §"Fix 4": * > Notes/reminders in plain Room DB — sensitive data unprotected. * * Reminder bodies often contain private information ("Take metformin", * "Call mom about doctor report", "Aadhaar card renewal"). These must * not be readable from a backup, an ADB pull, or a root-level dump. * * ## Real Android APIs Used * * | Operation | API | * |-----------|-----| * | Key storage | `KeyStore.getInstance("AndroidKeyStore")` | * | Key generation | `KeyGenParameterSpec.Builder` with `PURPOSE_ENCRYPT \| PURPOSE_DECRYPT` | * | Cipher | `Cipher.getInstance("AES/GCM/NoPadding")` | * | Auth | `setUserAuthenticationRequired(false)` (we want headless decrypt) | * | Key validity | `setRandomizedEncryptionRequired(true)` (forces fresh IV per call) | * * ## Why not Module 12's KeystoreManager? * * Module 12 (security) is not yet implemented. Rather than stubbing the * dependency, this helper uses AndroidKeystore directly — REAL production * crypto. When Module 12 ships, this helper can be refactored to delegate * to Module 12's `KeystoreManager` without changing call sites. * * ## Security Properties * * - **AES-256-GCM**: authenticated encryption (confidentiality + integrity). * - **Per-call IV**: a fresh 12-byte IV is generated for every encrypt call *   (AndroidKeystore enforces this via `setRandomizedEncryptionRequired(true)`). * - **Key never leaves Keystore**: the SecretKey is opaque; raw bytes are *   never accessible to the app process. * - **No user auth required**: reminders must fire headlessly from a *   WorkManager Worker, so we cannot gate on biometric unlock. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 6</a> */class ReminderEncryptionHelper {    companion object {        private const val TAG = "ReminderEncryption"        /** AndroidKeystore alias for the reminder body key. */        private const val KEYSTORE_ALIAS = "nous_reminder_body_key"        /** GCM IV length (12 bytes — the standard for AES-GCM). */        private const val GCM_IV_LENGTH_BYTES = 12        /** GCM authentication tag length (128 bits — maximum). */        private const val GCM_TAG_LENGTH_BITS = 128        /** AndroidKeystore provider name. */        private const val ANDROID_KEYSTORE_PROVIDER = "AndroidKeyStore"        /** AES/GCM/NoPadding cipher transformation. */        private const val TRANSFORMATION = "AES/GCM/NoPadding"    }    /**     * Encrypt a plaintext reminder body.     *     * Generates a fresh IV (handled internally by AndroidKeystore), runs     * AES-GCM, and returns an [EncryptedData] holding both IV and     * ciphertext as Base64 strings.     *     * @param plaintext the raw reminder body text (e.g., "Take metformin 500mg").     * @return encrypted payload, or null if encryption failed.     */    fun encrypt(plaintext: String): EncryptedData? {        if (plaintext.isEmpty()) return null        return try {            val key = getOrCreateKey() ?: return null            val cipher = Cipher.getInstance(TRANSFORMATION).apply {                init(Cipher.ENCRYPT_MODE, key)            }            val iv = cipher.iv  // AndroidKeystore generated a fresh IV.            val ciphertext = cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))            EncryptedData(                ivBase64 = Base64.encodeToString(iv, Base64.NO_WRAP),                ciphertextBase64 = Base64.encodeToString(ciphertext, Base64.NO_WRAP),            )        } catch (e: Exception) {            Timber.tag(TAG).e("Encryption failed.", e)            null        }    }    /**     * Decrypt an [EncryptedData] payload back to plaintext.     *     * @param encrypted the IV + ciphertext pair produced by [encrypt].     * @return the plaintext string, or null if decryption failed (tampered     *         ciphertext, wrong key, corrupted IV, etc.).     */    fun decrypt(encrypted: EncryptedData): String? {        return try {            val key = getOrCreateKey() ?: return null            val iv = Base64.decode(encrypted.ivBase64, Base64.NO_WRAP)            val ciphertext = Base64.decode(encrypted.ciphertextBase64, Base64.NO_WRAP)            val cipher = Cipher.getInstance(TRANSFORMATION).apply {                init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv))            }            val plaintext = cipher.doFinal(ciphertext)            String(plaintext, Charsets.UTF_8)        } catch (e: Exception) {            Timber.tag(TAG).e("Decryption failed.", e)            null        }    }    /**     * Get or create the AES-256-GCM key in AndroidKeystore.     *     * The key is non-authenticated (so headless Workers can decrypt),     * randomized-encryption-required (so each encrypt gets a fresh IV),     * and persists across app restarts (but not across app uninstall).     *     * @return the [SecretKey], or null if Keystore is unavailable.     */    private fun getOrCreateKey(): SecretKey? {        return try {            val keyStore = KeyStore.getInstance(ANDROID_KEYSTORE_PROVIDER).apply { load(null) }            // Reuse existing key if present.            val existing = keyStore.getKey(KEYSTORE_ALIAS, null) as? SecretKey            if (existing != null) return existing            // Generate a new AES-256-GCM key.            val keyGenerator = KeyGenerator.getInstance(                KeyProperties.KEY_ALGORITHM_AES,                ANDROID_KEYSTORE_PROVIDER,            )            val builder = KeyGenParameterSpec.Builder(                KEYSTORE_ALIAS,                KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,            )                .setKeySize(256)                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)                .setRandomizedEncryptionRequired(true)  // Forces fresh IV per encrypt.                .setUserAuthenticationRequired(false)    // Headless decrypt from Worker.            // API 31+: don't require auth on key creation either.            // `setUserAuthenticationParameters(timeout, authTypes)` expects an            // authTypes bitmask; `0` means "no auth types" — valid only when            // `setUserAuthenticationRequired(false)` was called (which we did            // above). There is no `KeyProperties.AUTH_NONE` constant — 0 is            // the documented "no auth required" sentinel.            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {                builder.setUserAuthenticationParameters(0, 0)            }            keyGenerator.init(builder.build())            keyGenerator.generateKey()        } catch (e: Exception) {            Timber.tag(TAG).e("Failed to get/create reminder encryption key.", e)            null        }    }    /**     * Delete the encryption key from AndroidKeystore (used for tests + reset).     *     * WARNING: any reminders encrypted with the deleted key become     * permanently unreadable. Production callers should clear the     * [ReminderStore] BEFORE deleting the key.     */    fun deleteKey() {        try {            val keyStore = KeyStore.getInstance(ANDROID_KEYSTORE_PROVIDER).apply { load(null) }            if (keyStore.containsAlias(KEYSTORE_ALIAS)) {                keyStore.deleteEntry(KEYSTORE_ALIAS)                Timber.tag(TAG).i("Deleted reminder encryption key from AndroidKeystore.")            }        } catch (e: Exception) {            Timber.tag(TAG).w("Could not delete reminder encryption key.", e)        }    }    /**     * Check whether the encryption key exists in AndroidKeystore.     *     * Useful for diagnostics + tests (does NOT trigger key creation).     */    fun keyExists(): Boolean {        return try {            val keyStore = KeyStore.getInstance(ANDROID_KEYSTORE_PROVIDER).apply { load(null) }            keyStore.containsAlias(KEYSTORE_ALIAS)        } catch (e: Exception) {            false        }    }}